using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using RaceDay.API.Controllers;
using RaceDay.API.DTOs;
using Xunit;

namespace Race_Day_Part_2.Test
{
    public class EventsControllerTests
    {
        [Fact]
        public void CreateEvent_ValidData_ReturnsOk()
        {
            // Arrange
            var controller = new EventsController();

            var httpContext = new DefaultHttpContext();
            httpContext.Session = new MockSession();
            httpContext.Session.SetString("Role", "Organiser");
            controller.ControllerContext = new ControllerContext { HttpContext = httpContext };

            var newEventDto = new EventCreateDto("Marathon Race", "Annual city run", DateTime.Now.AddDays(30), "City Center", 42.2, "Run");

            // Act
            var result = controller.Create(newEventDto);

            // Assert
            var okResult = Assert.IsType<OkObjectResult>(result);
            Assert.Equal(200, okResult.StatusCode);
        }
    }

    // Helper class to mock session state storage inside unit tests
    public class MockSession : ISession
    {
        private readonly Dictionary<string, byte[]> _store = new();
        public bool IsAvailable => true;
        public string Id => Guid.NewGuid().ToString();
        public IEnumerable<string> Keys => _store.Keys;
        public void Clear() => _store.Clear();
        public Task CommitAsync(System.Threading.CancellationToken token) => Task.CompletedTask;
        public Task LoadAsync(System.Threading.CancellationToken token) => Task.CompletedTask;
        public void Remove(string key) => _store.Remove(key);
        public void Set(string key, byte[] value) => _store[key] = value;
        public bool TryGetValue(string key, out byte[] value) => _store.TryGetValue(key, out value!);
    }
